function trFit(ri,k,v,c){var s=0;if(k==='vTrait'){var cls=TRC[v]||'n';if(cls==='f'&&c.sex!=='女')s-=12;if(cls==='m'&&c.sex!=='男')s-=12;if(/萝莉|少女|正太|童声/.test(v)&&c.ageN>30)s-=4;if(/奶狗|少年|学长|狼狗/.test(v)&&c.ageN>32)s-=3;if(/御姐|女王|知性|淑女|少御/.test(v)&&c.ageN<25)s-=2;if(/大叔|老者/.test(v)&&c.ageN<45)s-=4;if(/霸总|磁性|播音/.test(v)&&c.ageN<25)s-=2;return s;}var tf=findF(ri,'vTrait'),P=tf?VTR[tf.val]:null;if(!P)return 0;var ix={vRange:0,vTimbre:1,vPhonation:2,vSpeed:3,vVolume:4}[k];if(ix==null)return 0;return P.split('|')[ix].split(',').indexOf(v)>=0?8:-2;}var VOICE5={vRange:1,vTimbre:1,vPhonation:1,vSpeed:1,vVolume:1};function orderOpts(ri,k,opts){var c=ctxOf(ri),w=wantOf(c),fw=famW(ri,k),ix={};if(VOICE5[k]&&findF(ri,'vTrait')){for(var q in w)w[q]=w[q]*0.35;}opts.forEach(function(v,i){ix[v]=i;});var arr=opts.map(function(v,i){return{v:v,i:i,s:tagScore(v,w)+tagScore(v,fw)+trFit(ri,k,v,c)};});arr.sort(function(a,b){return(b.s-a.s)||(a.i-b.i);});return{list:arr.map(function(x){return x.v;})};}
function fitOf(ri,k,opts){var f=findF(ri,k),o=orderOpts(ri,k,opts),list=o.list.slice();var cur=f?((f.multi&&f.vals)?f.vals.filter(Boolean):(f.val?[f.val]:[])):[];var n=Math.min(6,opts.length);   /* 单列＝推荐项 5-8（取 6）· 当前值在推荐内才置顶 · 全池只在两栏 */var top=list.slice(0,n),rest=list.slice(n);cur.forEach(function(v){var i=top.indexOf(v);if(i>0){top.splice(i,1);top.unshift(v);}});return{list:list,top:top,rest:rest};}

